__global__ void kernel(int *out) {
    out[0] = if_chain();
}

int main() {
    int h_out[10][1] = {{}};
    int **d_out;
    cudaMalloc((void**)d_out, sizeof(int));
    kernel<<<10, 1>>>(d_out);
    cudaMemcpy(h_out, d_out, sizeof(int), cudaMemcpyDeviceToHost);
    cudaDeviceSynchronize();
    for (int i = 0; i < 10; i++) {
    std::cout << "Result: " << h_out[i][0] << std::endl;
    }
    cudaFree(d_out);
    return 0;
}
